package com.ahotel.servlet;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.time.LocalDateTime;@WebServlet("/legacy-status") public class SystemStatusServlet extends HttpServlet {@Override protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{p.setContentType("text/html;charset=UTF-8");p.getWriter().println("<h2>Hotel Management System - Servlet Status</h2><p>Servlet API is working.</p><p>Server time: "+LocalDateTime.now()+"</p><a href='/dashboard'>Open JSP dashboard</a>");}}